export interface ValidationResult {
    ready: boolean;
    risksDetected: string[];
    criticalBlockers: string[];
    score: number; // 0 - 100 deployment readiness score
}

export interface HardenedConfig {
    originalConfig: any;
    hardenedAt: number;
    securityLevel: 'MAXIMUM' | 'HIGH' | 'DEFAULT';
    enforcedSettings: Record<string, any>;
}

export function validateDeploymentReady(config: any): ValidationResult {
    const risksDetected: string[] = [];
    const criticalBlockers: string[] = [];

    // Check baseline configurations
    const debugMode = config?.debug ?? false;
    const sslForced = config?.forceSsl ?? false;
    const replicationCount = config?.maxReplicas ?? 1;
    const walEnabled = config?.walEnabled ?? false;
    const rateLimitEnabled = config?.rateLimitEnabled ?? false;

    if (debugMode) {
        risksDetected.push('RISK: Debug mode is active. This can expose sensitive internal logs in production.');
    }
    if (!sslForced) {
        criticalBlockers.push('BLOCKER: Secure transport (SSL/TLS) is not forced on communication channels.');
    }
    if (replicationCount > 10) {
        risksDetected.push(`RISK: Replication footprint (${replicationCount}) exceeds nominal economic budget bounds.`);
    }
    if (!walEnabled) {
        criticalBlockers.push('BLOCKER: Write-Ahead Log (WAL) is disabled. Replay durability cannot be guaranteed.');
    }
    if (!rateLimitEnabled) {
        risksDetected.push('RISK: Rate limiting is disabled. Susceptible to API flooding or denial of service.');
    }

    // Score calculation
    let score = 100;
    score -= criticalBlockers.length * 40;
    score -= risksDetected.length * 15;
    score = Math.max(0, score);

    const ready = criticalBlockers.length === 0 && score >= 70;

    return {
        ready,
        risksDetected,
        criticalBlockers,
        score
    };
}

export function applySafetyDefaults(config: any): HardenedConfig {
    const enforcedSettings: Record<string, any> = { ...config };

    // Force standard fail-closed properties
    enforcedSettings.debug = false;
    enforcedSettings.forceSsl = true;
    enforcedSettings.walEnabled = true;

    if (enforcedSettings.rateLimitEnabled === undefined) {
        enforcedSettings.rateLimitEnabled = true;
    }
    if (enforcedSettings.maxReplicas === undefined || enforcedSettings.maxReplicas > 5) {
        enforcedSettings.maxReplicas = 5; // Enforce maximum budget cap
    }

    return {
        originalConfig: config,
        hardenedAt: Date.now(),
        securityLevel: 'MAXIMUM',
        enforcedSettings
    };
}

import { validateDeploymentReady, applySafetyDefaults } from './index.js';

function assert(condition: any, message: string) {
    if (!condition) {
        console.error(`❌ FAILED: ${message}`);
        throw new Error(message);
    } else {
        console.log(`✅ PASSED: ${message}`);
    }
}

async function runTests() {
    console.log('\n==================================================');
    console.log('🚀 TESTING DEPLOYMENT HARDENING LAYER');
    console.log('==================================================\n');

    try {
        console.log('👉 Running Test 1: Validate highly vulnerable config...');
        const weakConfig = {
            debug: true,
            forceSsl: false,
            maxReplicas: 12,
            walEnabled: false,
            rateLimitEnabled: false
        };
        const validation1 = validateDeploymentReady(weakConfig);
        assert(validation1.ready === false, 'Config should not be ready');
        assert(validation1.criticalBlockers.length === 2, 'Should have 2 critical blockers (SSL, WAL)');
        assert(validation1.risksDetected.length === 3, 'Should have 3 risks');
        assert(validation1.score === 0, 'Score should be 0 due to penalties');

        console.log('\n👉 Running Test 2: Validate healthy config...');
        const healthyConfig = {
            debug: false,
            forceSsl: true,
            maxReplicas: 3,
            walEnabled: true,
            rateLimitEnabled: true
        };
        const validation2 = validateDeploymentReady(healthyConfig);
        assert(validation2.ready === true, 'Config should be ready');
        assert(validation2.criticalBlockers.length === 0, 'Should have 0 blockers');
        assert(validation2.risksDetected.length === 0, 'Should have 0 risks');
        assert(validation2.score === 100, 'Score should be 100');

        console.log('\n👉 Running Test 3: Apply safety defaults to vulnerable config...');
        const hardenedResult = applySafetyDefaults(weakConfig);
        assert(hardenedResult.securityLevel === 'MAXIMUM', 'Security level must be MAXIMUM');
        assert(hardenedResult.enforcedSettings.debug === false, 'Debug should be forced false');
        assert(hardenedResult.enforcedSettings.forceSsl === true, 'SSL should be forced true');
        assert(hardenedResult.enforcedSettings.walEnabled === true, 'WAL should be forced true');
        assert(hardenedResult.enforcedSettings.maxReplicas === 5, 'Max replicas should be capped at 5');

        console.log('\n==================================================');
        console.log('🎉 DEPLOYMENT HARDENING LAYER PASSED ALL TESTS!');
        console.log('==================================================\n');
        process.exit(0);
    } catch (error) {
        console.error('\n❌ TEST RUN FAILED:\n', error);
        process.exit(1);
    }
}

runTests();
